{'Fn::Sub': 'import json\nimport boto3\nimport cfnresponse\nidentitystore = boto3.client(\'identitystore\')\n\ndef lambda_handler(event, context):\n  print(f"Event : {json.dumps(event)}")\n  response_data = {}\n\n  try:\n    request_type = event["RequestType"]\n    user_name = event["ResourceProperties"].get("UserName", "sample")\n\n    if not user_name:\n      response_data["Reason"] = "No UserName"\n      cfnresponse.send(event, context, cfnresponse.FAILED, response_data)\n      return\n\n    if request_type == "Create" or request_type == "Update":\n      try:\n        user_params = {\n          \'IdentityStoreId\': \'${IamIdentityCenterInstance.IdentityStoreId}\',\n          \'UserName\': user_name,\n          \'DisplayName\': user_name,\n          \'Name\': {\n            \'GivenName\': \'Test\',\n            \'FamilyName\': \'User\'\n          },\n          \'Emails\': [\n            {\n                \'Value\': \'test@test.com\',\n                \'Type\': \'work\',\n                \'Primary\': True\n            }\n          ]\n        }\n        response = identitystore.create_user(**user_params)\n        response_data["UserId"] = response["UserId"]\n      except Exception as e:\n          response_data["Reason"] = str(e)\n          cfnresponse.send(event, context, cfnresponse.FAILED, response_data)\n          return\n\n    elif request_type == "Delete":\n      response_data["Message"] = "Custom Resource Deleted"\n\n    cfnresponse.send(event, context, cfnresponse.SUCCESS, response_data)\n\n  except Exception as e:\n    response_data["Reason"] = str(e)\n    cfnresponse.send(event, context, cfnresponse.FAILED, response_data)\n'}